def run_agent(goal, call_model, tools, max_steps=10):
    messages = [{'role': 'user', 'content': goal}]          # perceive: initial state
    for step in range(max_steps):
        decision = call_model(messages)                    # reason
        if decision['type'] == 'final':
            return decision['content']
        name, args = decision['tool'], decision['args']
        try:
            result = tools[name](**args)                   # act
        except Exception as exc:
            result = f'error: {exc}'
        messages.append({'role': 'assistant', 'content': f'call {name} {args}'})
        messages.append({'role': 'tool', 'content': str(result)})  # observe
    return 'Stopped: step limit reached without a final answer.'

